S = "Hakeem Force Academy"
QS = [
(S, "Which one is the odd one out: Zebra, Donkey, Horse, Kangaroo?", ["Zebra", "Donkey", "Kangaroo", "Horse"], 2,
 "Zebra, donkey and horse all belong to the horse family (Equidae). A kangaroo is a marsupial that carries its young in a pouch.",
 "Kangaroos are native to Australia and move by hopping.", [4110]),
(S, "How many peaks of Pakistan are higher than 8000 metres?", ["3", "4", "5", "6"], 2,
 "Pakistan has five peaks above 8000 m: K2, Nanga Parbat, Gasherbrum I, Broad Peak and Gasherbrum II. Most of them are in the Karakoram range.",
 "K2 at about 8611 m is the second highest mountain in the world.", [877]),
(S, "Which is the highest battlefield in the world?", ["Kargil", "Siachen Glacier", "Wakhan Corridor", "Khyber Pass"], 1,
 "The Siachen Glacier in the Karakoram, with posts above 6000 m, is called the highest battlefield in the world. India and Pakistan have faced each other there since 1984.",
 "Siachen lies in the Karakoram range in the Gilgit-Baltistan and Ladakh region.", [4071]),
(S, "Ahmad is 5 years old and his sister is three times his age. What is his sister's age?", ["12 years", "15 years", "18 years", "8 years"], 1,
 "Sister's age = 3 x 5 = 15 years.",
 "In such questions the age difference between two people always stays the same.", [1534]),
(S, "Ali is 3 years old and his sister is three times his age. What will be his sister's age when Ali is 8 years old?", ["24 years", "9 years", "14 years", "17 years"], 2,
 "Sister is 3 x 3 = 9 years now, so the age gap is 9 - 3 = 6 years. When Ali is 8, sister is 8 + 6 = 14 years.",
 "The gap between two ages never changes with time.", [1542]),
(S, "Ali is 3 years old and his sister is three times his age. What will be his sister's age when Ali is 12 years old?", ["36 years", "18 years", "21 years", "15 years"], 1,
 "Sister is 3 x 3 = 9 years now, so the gap is 6 years. When Ali is 12, sister is 12 + 6 = 18 years.",
 "Always find the gap first, then add it to the new age.", [1544]),
(S, "Ali is 5 years old and his sister is three times his age. When Ali is 7 years old, what will be his sister's age?", ["21 years", "15 years", "19 years", "17 years"], 3,
 "Sister is 3 x 5 = 15 years now, so the gap is 10 years. When Ali is 7, sister is 7 + 10 = 17 years.",
 "After 2 years both ages rise by 2 (15 + 2 = 17).", [1546]),
(S, "Ahmed is 5 years old and his sister is four times his age. When Ahmed is 12 years old, what is his sister's age?", ["27 years", "48 years", "20 years", "32 years"], 0,
 "Sister is 4 x 5 = 20 years now, so the gap is 15 years. When Ahmed is 12, sister is 12 + 15 = 27 years.",
 "After 7 years both ages rise by 7 (20 + 7 = 27).", [895]),
(S, "What is the highest peak of the Himalayas?", ["K2", "Kanchenjunga", "Mount Everest", "Nanga Parbat"], 2,
 "Mount Everest, on the Nepal-China border, is the highest peak of the Himalayas and of the world. Its official height is about 8849 m.",
 "Everest is called Sagarmatha in Nepal and Chomolungma in Tibet.", [3131, 3134]),
(S, "Who was known as the Ambassador of Hindu-Muslim Unity in the subcontinent?", ["Allama Iqbal", "Quaid-e-Azam Muhammad Ali Jinnah", "Liaquat Ali Khan", "Sir Syed Ahmad Khan"], 1,
 "Muhammad Ali Jinnah worked for Hindu-Muslim unity in the early part of his career, including the 1916 Lucknow Pact. Sarojini Naidu gave him this title.",
 "Jinnah was a member of the Indian National Congress before he led the Muslim League.", [61, 770]),
(S, "Which river do Hindus in India regard as sacred?", ["Indus", "Brahmaputra", "Ganges (Ganga)", "Yamuna"], 2,
 "Hindus consider the Ganges (Ganga) the holiest river and bathe in it at places like Varanasi and Haridwar. It is worshipped as the goddess Ganga.",
 "The Ganges flows from the Himalayas to the Bay of Bengal.", [4072, 4283, 4286, 4287]),
(S, "On which date was the atomic bomb dropped on Hiroshima?", ["9 August 1945", "6 August 1945", "15 August 1945", "2 September 1945"], 1,
 "The United States dropped the first atomic bomb on Hiroshima on 6 August 1945, during World War II.",
 "A second bomb hit Nagasaki on 9 August 1945, and Japan surrendered soon after.", [958, 3064, 263]),
(S, "In which country is the city of Hiroshima, which was hit by an atomic bomb in 1945?", ["China", "Japan", "South Korea", "Germany"], 1,
 "Hiroshima is a city in Japan, on the island of Honshu. The US dropped an atomic bomb on it on 6 August 1945.",
 "Hiroshima Peace Memorial (the Atomic Bomb Dome) is a UNESCO World Heritage Site.", [3837]),
(S, "Which is the highest award for bravery given in the Pakistan Armed Forces, often called the hero medal of honour?", ["Nishan-e-Haider", "Sitara-e-Jurat", "Hilal-e-Imtiaz", "Tamgha-e-Basalat"], 0,
 "Nishan-e-Haider is the highest military gallantry award of Pakistan and is given for extraordinary bravery in battle. Only a few soldiers have received it.",
 "Major Raja Aziz Bhatti was among the recipients, for the 1965 war.", [3125]),
(S, "What is the meaning of the idiom 'flogging a dead horse'?", ["Wasting effort on something that cannot succeed", "Training a horse hard", "Being very cruel to animals", "Working very fast"], 0,
 "To flog a dead horse means to waste effort on something that is already finished or hopeless.",
 "A similar idiom is 'beating a dead horse'.", [3200]),
(S, "Which country hosted the G20 summit in 2023?", ["Indonesia", "Brazil", "India", "Italy"], 2,
 "India hosted the 2023 G20 summit in New Delhi under its presidency. The African Union became a permanent member there.",
 "Indonesia hosted in 2022, Brazil in 2024 and South Africa in 2025.", [3958, 3960]),
(S, "What is the meaning of the idiom 'to blow hot and cold'?", ["To feel very tired", "To change opinion again and again", "To be very angry", "To be good at cooking"], 1,
 "To blow hot and cold means to keep changing one's mind or attitude about something, being enthusiastic and then not.",
 "The idiom comes from an old fable of a man who blew on his hands to warm them and on his soup to cool it.", [3203]),
(S, "For how many years are the members of the Senate (Upper House of Pakistan) elected?", ["4 years", "5 years", "6 years", "3 years"], 2,
 "Senators serve a term of six years. Half of the members retire every three years.",
 "The National Assembly, in contrast, has a term of five years.", [1909]),
(S, "How many members does the National Assembly (Lower House) of Pakistan have, including reserved seats?", ["342", "336", "100", "104"], 0,
 "The National Assembly has 266 general seats, 60 seats for women and 10 for non-Muslims, a total of 342.",
 "A simple majority needs 172 members.", [3277]),
(S, "Where is the city of Hubli (Hubballi) located?", ["Maharashtra, India", "Karnataka, India", "Sindh, Pakistan", "Tamil Nadu, India"], 1,
 "Hubli (Hubballi) is a major city in the state of Karnataka in India, twinned with Dharwad.",
 "The capital of Karnataka is Bengaluru.", [3729]),
(S, "In which battle were the most Huffaz (memorisers) of the Quran martyred?", ["Battle of Badr", "Battle of Uhud", "Battle of Yamama", "Battle of Khandaq"], 2,
 "Many Huffaz were martyred at Yamama (12 AH) against the false prophet Musailma. This led Hazrat Umar (RA) to urge Hazrat Abu Bakr (RA) to compile the Quran in one book.",
 "Reports of the number martyred in this battle vary by source (commonly about 70 Huffaz).", [944]),
(S, "Justice Musarrat Hilali took oath in 2023 as the first woman Chief Justice of which high court?", ["Lahore High Court", "Sindh High Court", "Peshawar High Court", "Islamabad High Court"], 2,
 "Justice Musarrat Hilali took oath as the first woman Chief Justice of the Peshawar High Court on 1 April 2023, in an acting capacity as per some reports. She later became a Supreme Court judge.",
 "Justice Tahira Safdar of the Balochistan High Court was the first woman chief justice of any high court in Pakistan (2018).", [2630, 2182, 2394]),
]
